use crate::hidden_anchor::{self, APP_DIR};

/// The most files of each side analyzed.
pub const MAX_FILES: usize = 400;

/// How strong a connection has to be to count as strong, or as moderate.
pub const STRONG: f32 = 2. / 3.;
pub const MODERATE: f32 = 1. / 3.;

/// The side of the project a file is on.
        }
    }
}

/// How strong a connection of `strength` is.
pub fn strength_label(strength: f32) -> &'static str {
    if strength >= STRONG {
        "Strong"
    } else if strength >= MODERATE {
        "Moderate"
    } else {
        "Weak"
    }
}

/// `path` as the agents and the report write it: relative to the project,
    }

    #[test]
    fn scores_and_strengths_are_named() {
        assert_eq!(Verdict::of(0), Verdict::Aligned);
        assert_eq!(Verdict::of(19), Verdict::Aligned);
        assert_eq!(Verdict::of(20), Verdict::Drifting);
        assert_eq!(Verdict::of(50), Verdict::Diverged);
        assert_eq!(strength_label(0.9), "Strong");
        assert_eq!(strength_label(0.4), "Moderate");
        assert_eq!(strength_label(0.1), "Weak");
    }

        connections:
            A connection joins a source file and a spec file. Its strength is
            the average of what both agents said of it, or what one said when
            only one mentioned it, from 0 to 1, and so is its divergence, which
            is unknown when neither agent said. Connections to files that aren't
            among the source or spec files are left out. A strength of two
            thirds or more is strong, one third or more moderate, and anything
            less weak.

            - divergence, for a source file as "Diverges from the spec", and for a spec file as "Implementation diverges", coloured as the score is
            - definition, as "Definition"

            Then, for a source file, "Filled in by the implementation", and for
            a spec file, "Gaps in the spec", listing them, or saying there are
            none. Then its connections to files on the other side, strongest
            first, each with the other file's path, a bar as long as the
            connection is strong, its strength as a percentage, whether it is
            strong, moderate, or weak, its divergence as a percentage when known,
            coloured as the score is, and what the agents noted of it. Clicking
            a connection switches to the other tree with that file selected and
            scrolled into view. With nothing selected, the details say to select
            a file. Once the results are in, the source file with the highest
            divergence is selected.

